    "name": "Curah_Hujan.htm",
    "title": "Grafik Hujan & Cerah",
    "content": "<!DOCTYPE html>\n<html lang=\"id\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Grafik Hujan & Cerah</title>\n\n<style>\nbody {\n  margin: 0;\n  padding: 0;\n  text-align: center;\n  font-family: Arial, sans-serif;\n  background: #f4f9fc;\n}\nh3 {\n  margin: 10px 0 1px;\n  color: #17435e;\n  letter-spacing: .1px;\n}\n.stats {\n  display: flex;\n  justify-content: center;\n  gap: 10px;\n  flex-wrap: wrap;\n  margin: 0 12px 10px;\n}\n.stat {\n  background: #fff;\n  border: 1px solid #d7e5ee;\n  border-radius: 5px;\n  padding: 8px 16px;\n  min-width: 20px;\n  box-shadow: 0 1px 3px rgba(23,67,94,.08);\n}\n.stat .num { font-size: 10px; font-weight: bold; line-height: 1.15; }\n.stat .lbl { font-size: 11px; color: #5a7284; text-transform: uppercase; letter-spacing: .6px; }\n.stat.rain .num { color: #1798b6; }\n.stat.sun  .num { color: #e8a13a; }\n.stat.pct  .num { color: #2e7d4f; }\ncanvas {\n  max-width: 200px;\n  margin: 4px auto 16px;\n  cursor: pointer;\n}\n</style>\n\n<!-- Chart.js CDN (SANGAT KOMPATIBEL) -->\n<script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n</head>\n\n<body>\n\n<h3>Curah Hujan September 2026</h3>\n\n<div class=\"stats\">\n  <div class=\"stat rain\"><div class=\"num\" id=\"nHujan\">0</div><div class=\"lbl\">Hari Hujan</div></div>\n  <div class=\"stat sun\"><div class=\"num\" id=\"nCerah\">31</div><div class=\"lbl\">Hari Cerah</div></div>\n  <div class=\"stat pct\"><div class=\"num\" id=\"nPct\">0%</div><div class=\"lbl\">% Hujan</div></div>\n</div>\n\n<canvas id=\"polarChart\"></canvas>\n\n<script>\nconst labels = Array.from({length:31}, (_,i)=> (i+1).toString());\n\n// 1 = hujan, 0 = cerah,\nconst rainDays = [20,21,27,28];\n\n// --- state interaktif (disinkronkan: grafik ⇄ kotak tanggal ⇄ statistik) ---\nconst rainSet = new Set(rainDays);\n\nconst data = labels.map(() => 1);\n\n// kartu statistik awal\ndocument.getElementById(\"nHujan\").textContent = rainSet.size;\ndocument.getElementById(\"nCerah\").textContent = 31 - rainSet.size;\ndocument.getElementById(\"nPct\").textContent   = Math.round(rainSet.size / 31 * 100) + \"%\";\n\nconst chart = new Chart(document.getElementById(\"polarChart\"), {\n  type: \"polarArea\",\n  data: {\n    labels: labels,\n    datasets: [{\n      data: data,\n      backgroundColor: labels.map(day =>\n        rainSet.has(parseInt(day)) ? \"#95faff\" : \"#ffffff\"\n      ),\n      borderColor: \"#a9a9a9\",\n      borderWidth: 1,\n      hoverBorderColor: \"#4da6b3\",\n      hoverBorderWidth: 2\n    }]\n  },\n  options: {\n    scales: {\n      r: {\n        ticks: { display: false },\n        grid: { color: \"#ccc\" }\n      }\n    },\n    plugins: {\n      legend: {\n        display: false // <-- Legenda disembunyikan di sini\n      },\n      tooltip: {\n        callbacks: {\n          label: function(ctx) {\n            const day = parseInt(ctx.label);\n            return rainSet.has(day)\n              ? \"Hari \" + day + \": Hujan — klik untuk cerah\"\n              : \"Hari \" + day + \": Cerah — klik untuk hujan\";\n          }\n        }\n      }\n    }\n  }\n});\n\n// deteksi klik pada segmen: hitung posisi sendiri (rect segar) dan cek\n// inRange tiap arc — tidak bergantung pada sistem event internal Chart.js\n// sehingga tetap akurat walau animasi/rAF tidak berjalan\nchart.canvas.addEventListener(\"click\", function (evt) {\n  const src = evt.changedTouches ? evt.changedTouches[0] : evt;\n  const rect = chart.canvas.getBoundingClientRect();\n  const x = src.clientX - rect.left;\n  const y = src.clientY - rect.top;\n  const meta = chart.getDatasetMeta(0);\n  for (let i = 0; i < meta.data.length; i++) {\n    if (meta.data[i].inRange(x, y, true)) { toggle(i + 1); break; }\n  }\n});\n\n// fallback render: jika rAF tidak berjalan (iframe tersembunyi dsb.),\n// gambar sekali secara sinkron agar grafik tetap muncul\nsetTimeout(function () {\n  try {\n    var ctx = chart.canvas.getContext(\"2d\");\n    var px = ctx.getImageData(Math.floor(chart.width / 2), Math.floor(chart.height / 2), 1, 1).data;\n    if (px[3] === 0) { chart.update(\"none\"); chart.draw(); }\n  } catch (e) {}\n}, 600);\n\nfunction toggle(day) {\n  if (rainSet.has(day)) rainSet.delete(day); else rainSet.add(day);\n  refresh();\n}\n\nfunction refresh() {\n  chart.data.datasets[0].backgroundColor = labels.map(day =>\n    rainSet.has(parseInt(day)) ? \"#95faff\" : \"#ffffff\"\n  );\n  chart.update();\n  document.getElementById(\"nHujan\").textContent = rainSet.size;\n  document.getElementById(\"nCerah\").textContent = 31 - rainSet.size;\n  document.getElementById(\"nPct\").textContent   = Math.round(rainSet.size / 31 * 100) + \"%\";\n}\n</script>\n\n</body>\n</html>"
